cat >> test/app.test.ts <<'EOF'

test("POST /login returns the api token without auth", async () => {
  const post = (body: unknown) =>
    fetch(`${base}/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const ok = await post({ email: "alice@example.com", password: "alice-password" });
  assert.equal(ok.status, 200);
  assert.deepEqual(await ok.json(), { token: "alice-token" });
  assert.equal((await post({ email: "alice@example.com", password: "wrong" })).status, 401);
  assert.equal((await post({ email: "nobody@example.com", password: "x" })).status, 401);
  assert.equal((await post({ email: "alice@example.com" })).status, 400);
});
EOF
